import React, { useEffect, useState } from 'react';
import { View, Text, FlatList, StyleSheet, Button } from 'react-native';
import { fetchWithAuth } from '../lib/api';

export default function ProfileScreen({ navigation }) {
  const [bookings, setBookings] = useState([]);
  const [reviews, setReviews] = useState([]);
  const [loginRequired, setLoginRequired] = useState(false);

  useEffect(() => {
    fetchMyData();
  }, []);

  const fetchMyData = async () => {
    try {
      const [bookingsRes, reviewsRes] = await Promise.all([
        fetchWithAuth('/api/bookings'),
        fetchWithAuth('/api/reviews/renter')
      ]);

      const [bookingsData, reviewsData] = await Promise.all([bookingsRes.json(), reviewsRes.json()]);
      setBookings(bookingsData);
      setReviews(reviewsData);
      setLoginRequired(false);
    } catch (error) {
      setLoginRequired(true);
      setBookings([]);
      setReviews([]);
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Profiili</Text>
      {loginRequired ? (
        <View>
          <Text style={styles.info}>Kirjaudu sisään nähdäksesi varaukset ja sinun arvostelusi.</Text>
          <Button title="Kirjaudu" onPress={() => navigation.navigate('Auth')} />
        </View>
      ) : (
        <>
          <Text style={styles.sectionTitle}>Omat varaukset</Text>
          <FlatList
            data={bookings}
            keyExtractor={(i) => i.id}
            ListEmptyComponent={<Text>Ei varauksia.</Text>}
            renderItem={({ item }) => (
              <View style={styles.item}>
                <Text style={styles.name}>{item.productId}</Text>
                <Text>{item.name} — {item.email}</Text>
              </View>
            )}
          />
          <Text style={styles.sectionTitle}>Sinulle annetut arvostelut</Text>
          <FlatList
            data={reviews}
            keyExtractor={(i) => i.id}
            ListEmptyComponent={<Text>Ei arvosteluja vielä.</Text>}
            renderItem={({ item }) => (
              <View style={styles.item}>
                <Text style={styles.name}>{item.reviewer} — {item.rating}/5</Text>
                <Text>{item.comment}</Text>
              </View>
            )}
          />
          <Button
            title="Arvioi vuokraaja"
            onPress={() => navigation.navigate('RenterReview')}
          />
        </>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 },
  title: { fontSize: 20, fontWeight: '700', marginBottom: 12 },
  sectionTitle: { fontSize: 16, fontWeight: '700', marginTop: 16, marginBottom: 8 },
  info: { marginBottom: 12, color: '#444' },
  item: { padding: 8, borderBottomWidth: 1, borderColor: '#eee' },
  name: { fontWeight: '600' }
});
